<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { Box, House, Lock, Download, Search, Plus, Refresh } from '@element-plus/icons-vue'
import { useApp } from '../store'
import { api, download, query } from '../api'
import { money, quantity } from '../utils'
import DataTable from '../components/DataTable.vue'
import Documents from './Documents.vue'
const app = useApp(), view = ref('balances'), warehouse = ref<any>(), search = ref(''), rows = ref<any[]>([]), stock = ref<any[]>([]), warehouses = ref<any[]>([]), busy = ref(false)
async function load() { if (view.value === 'documents') return; busy.value = true; try { const params = query({ warehouse_id: warehouse.value, search: search.value }); const endpoint = view.value === 'batches' ? 'balances' : view.value; const result = await api('/inventory/' + endpoint + '?' + params); rows.value = result.items; if (['balances', 'batches'].includes(view.value)) stock.value = result.items } catch {} finally { busy.value = false } }
watch([view, warehouse], load); watch(() => app.tick, load); onMounted(async () => { load(); try { warehouses.value = (await api('/masters/warehouse?active=true')).items; stock.value = (await api('/inventory/balances')).items } catch {} })
const visibleRows = computed(() => view.value === 'batches' ? rows.value.filter(r => r.batch) : rows.value)
const inventoryKinds = computed(() => app.kinds.filter(k => k.module === 'inventory'))
const totals = computed(() => ({ products: new Set(stock.value.map(r => r.product_id)).size, quantity: stock.value.reduce((n, r) => n + Number(r.quantity), 0), reserved: stock.value.reduce((n, r) => n + Number(r.reserved), 0), value: app.costVisible ? stock.value.reduce((n, r) => n + Number(r.value), 0) : null }))
const columns = computed(() => {
  if (view.value === 'transactions') return [{ key: 'number', label: '来源单号', type: 'link', minWidth: 205 }, { key: 'product_name', label: '商品', minWidth: 150 }, { key: 'warehouse_name', label: '仓库', minWidth: 100 }, { key: 'batch', label: '批次' }, { key: 'before_quantity', label: '变动前', type: 'qty' }, { key: 'delta', label: '变动数量', type: 'qty' }, { key: 'after_quantity', label: '变动后', type: 'qty' }, { key: 'cost_delta', label: '成本变动', type: 'money', hidden: !app.costVisible }, { key: 'operator', label: '操作人' }, { key: 'created_at', label: '时间', type: 'datetime', minWidth: 175 }]
  if (view.value === 'serials') return [{ key: 'serial', label: '序列号', minWidth: 200 }, { key: 'product_code', label: '商品编码' }, { key: 'product_name', label: '商品名称', minWidth: 170 }, { key: 'warehouse_name', label: '仓库' }, { key: 'location_name', label: '库位' }, { key: 'batch', label: '批次' }, { key: 'state', label: '状态', type: 'status' }, { key: 'updated_at', label: '最后变更', type: 'datetime', minWidth: 175 }]
  return [{ key: 'product_code', label: '商品编码', minWidth: 120 }, { key: 'product_name', label: '商品名称', minWidth: 180 }, { key: 'warehouse_name', label: '仓库', minWidth: 120 }, { key: 'location_name', label: '库位', minWidth: 100 }, { key: 'batch', label: '批次', minWidth: 100 }, { key: 'unit', label: '单位', width: 65 }, { key: 'quantity', label: '现存数量', type: 'qty' }, { key: 'reserved', label: '订单占用', type: 'qty' }, { key: 'available', label: '可用数量', type: 'qty' }, { key: 'avg_cost', label: '平均成本', type: 'qty', hidden: !app.costVisible }, { key: 'value', label: '库存金额', type: 'money', minWidth: 125, hidden: !app.costVisible }]
})
function create(kind: string) { app.openDoc(0, kind, warehouse.value ? { kind, warehouse_id: warehouse.value, date: new Date().toLocaleDateString('sv-SE'), data: {}, items: [] } : null) }
function exportRows() { download('/export?' + query({ type: view.value === 'balances' || view.value === 'batches' ? 'inventory' : view.value, warehouse_id: warehouse.value, search: search.value })) }
</script>
<template>
  <div class="page-head"><div><h1>库存管理</h1><p>看清现存与可用库存，追踪每一件商品的来龙去脉。</p></div><div class="page-actions"><el-button v-if="view !== 'documents'" :icon="Download" @click="exportRows">导出明细</el-button><el-dropdown v-if="app.can('inventory.edit')" trigger="click" @command="create"><el-button type="primary" :icon="Plus" :disabled="!app.writable('inventory')">库存业务</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="k in inventoryKinds" :key="k.key" :command="k.key">{{ k.name }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></div>
  <div class="metric-grid"><div class="metric-card"><div class="metric-label">在库商品种类<div class="metric-icon"><el-icon><Box/></el-icon></div></div><div class="metric-value">{{ totals.products }}<small style="margin-left:7px">种</small></div><div class="metric-footer">按当前仓库与查询条件统计</div></div><div class="metric-card"><div class="metric-label">现存数量合计<div class="metric-icon green"><el-icon><House/></el-icon></div></div><div class="metric-value">{{ quantity(totals.quantity) }}</div><div class="metric-footer">包含批次、库位与委托库存</div></div><div class="metric-card"><div class="metric-label">销售订单占用<div class="metric-icon orange"><el-icon><Lock/></el-icon></div></div><div class="metric-value">{{ quantity(totals.reserved) }}</div><div class="metric-footer">审核销售订单后锁定库存</div></div><div class="metric-card"><div class="metric-label">库存总金额<div class="metric-icon violet"><el-icon><Box/></el-icon></div></div><div class="metric-value"><small>¥</small>{{ money(totals.value) }}</div><div class="metric-footer">移动加权平均成本</div></div></div>
  <div class="subnav panel mb16"><button v-for="v in [{k:'balances',n:'库存余额'},{k:'transactions',n:'库存流水'},{k:'batches',n:'批次库存'},{k:'serials',n:'序列号追踪'},{k:'documents',n:'库存业务单据'}]" :key="v.k" :class="{selected:view === v.k}" @click="view = v.k">{{ v.n }}</button></div>
  <Documents v-if="view === 'documents'" module="inventory" embedded/>
  <section v-else class="panel"><div class="filter-row"><el-input v-model="search" :prefix-icon="Search" :placeholder="view === 'serials' ? '序列号或商品名称' : '商品、编码、批次或单据编号'" clearable @clear="load" @keyup.enter="load"/><el-select v-if="view !== 'serials'" v-model="warehouse" placeholder="全部仓库" clearable filterable><el-option v-for="w in warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select><el-button type="primary" plain @click="load">查询</el-button><div class="spacer"></div><el-button text :icon="Refresh" @click="load">刷新</el-button></div><DataTable :rows="visibleRows" :columns="columns" :loading="busy" empty="暂无库存记录，请先审核采购入库或期初库存单" @open="id => app.openDoc(id)"/></section>
</template>
